/* From Uiverse.io by Cybercom682 - Tags: input, number, quantity */
.__UIV_SCOPE__ .number-control {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .number-left::before,
.__UIV_SCOPE__ .number-right::after {
  content: attr(data-content);
  background-color: #333333;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid black;
  width: 20px;
  color: white;
  transition: background-color 0.3s;
  cursor: pointer;
}

.__UIV_SCOPE__ .number-left::before {
  content: "-";
}

.__UIV_SCOPE__ .number-right::after {
  content: "+";
}

.__UIV_SCOPE__ .number-quantity {
  padding: 0.25rem;
  border: 0;
  width: 50px;
  -moz-appearance: textfield;
  border-top: 1px solid black;
  border-bottom: 1px solid black;
}

.__UIV_SCOPE__ .number-left:hover::before,
.__UIV_SCOPE__ .number-right:hover::after {
  background-color: #666666;
}
